    return true;
  }

  /// Shows [value], the installed package's member, standing for [requested], beside [failure].
  void _showPackage(T value, List<Object?> requested, CruftFreeException failure) {
    _cancelStale();
    _value = value;
    _valueInputs = requested;
    _status = _BindingStatus.loaded;
    _error = failure;
    _shown = _KeptShown.package;
  }

  /// The member of the copy installed under the binding's key, or `null` when none is or it
  /// cannot be read: the route's failure is shown then.
  Future<({T value})?> _packageLookup(PackageFallback<T> package) async {
    try {
      final value = await package.read();
      return value == null ? null : (value: value);
    } on Object catch (error) {
      _keptLog.warning('A package fallback could not be read (${error.runtimeType}).');
      return null;
    }
  }

  /// The device turned online or offline. Back online, a copy shown -- a kept copy, fresh or
  /// turned stale, or the installed package's -- owes a request, issued once the gate is open.
  /// Offline, the live answer shown is shown as its kept copy while that copy is fresh.
  void _deviceTurned() {
    final device = _device;
    if (device == null || _disposed) {
      return;
    }
    final online = device.isOnline;
    if (online == _online) {
      return;
    }
    _online = online;
    if (online) {
      if (_shown != _KeptShown.live) {
        _owed = true;
        notifyListeners();
        sync();
      }
      return;
    }
    final kept = _kept;
    final live = _liveCopy;
    if (kept != null && _shown == _KeptShown.live && _status == _BindingStatus.loaded && live != null && live.key == _wantedKey && _fresh(kept, live.entry)) {
      _showKept(kept, live.entry, _valueInputs, _offlineFailure);
      notifyListeners();
    }
  }

  /// Keeps [value], the answer for [key], as its copy. Keeping is best effort (a
  /// full or absent store): the live answer stands either way.
  Future<void> _save(KeptCall<T> kept, String key, T value) async {
    final entry = KeptEntry<T>(kept.read.device.nowMs, value);
    _liveCopy = (key: key, entry: entry);
    try {
      await kept.read.device.put(key, encodeKeptEntry(kept.read.codec, entry.savedAtMs, value));
    } on Object catch (error) {
      _keptLog.warning('${kept.read.route.route}: an answer could not be kept (${error.runtimeType}).');
    }
  }

  /// The copy the store keeps under [key], or `null` when it keeps none this rule can read.
  Future<KeptEntry<T>?> _lookup(KeptCall<T> kept, String key) async {
    final String? bytes;
    try {
      bytes = await kept.read.device.get(key);
    } on Object catch (error) {
      _keptLog.warning('${kept.read.route.route}: the kept copies could not be read (${error.runtimeType}).');
      return null;
    }
    if (bytes == null) {
      return null;
    }
    try {
      return decodeKeptEntry(kept.read.codec, bytes);
    } on Object {
      // Not a copy this rule kept of this read: it is never shown.
      _keptLog.warning('${kept.read.route.route}: an unreadable kept copy was ignored.');
      return null;
    }
  }

  @override
  void dispose() {
    _disposed = true;
    _polling = false;
    _stopPolling();
    _clearPause();
    _cancelStale();
    _device?.removeListener(_deviceTurned);
    super.dispose();
  }
}

/// How often a paused binding counts down the `pausedForMs` it reports, in milliseconds.
const int _pauseCountdownMs = Duration.millisecondsPerSecond;

/// What a paginated route's position counts, as its backend declares.
enum PositionAdvance { rowOffset, pageIndex }

/// The rows the page shown covers (`26-50` of `340`), numbered from the first row overall.
class PageRange {
  const PageRange(this.from, this.to, this.total);

  final int from;
  final int to;
  final int total;
}

/// Pages always shown at each end of the pager's window.
const int _pagerBoundaryCount = 1;

/// Pages shown on each side of the current page.
const int _pagerSiblingCount = 1;

/// The page numbers a pager shows: the first and last `_pagerBoundaryCount`, and the
/// `_pagerSiblingCount` either side of the current page -- clamped, de-duplicated and
/// ascending, with `null` (an ellipsis) between two that differ by more than one.
/// `pageIndex` is zero-based; the entries are 1-based.
List<int?> pageWindow(int pageCount, int pageIndex) {
  if (pageCount == 0) {
    return const [];
  }
  final current = pageIndex + 1;
  final shown = <int>{};
  void show(int from, int to) {
    for (var page = from < 1 ? 1 : from; page <= (to > pageCount ? pageCount : to); page++) {
      shown.add(page);
    }
  }

  show(1, _pagerBoundaryCount);
  show(current - _pagerSiblingCount, current + _pagerSiblingCount);
  show(pageCount - _pagerBoundaryCount + 1, pageCount);
  final entries = <int?>[];
  var previous = 0;
  for (final page in (shown.toList()..sort())) {
    if (previous != 0 && page - previous > 1) {
      entries.add(null);
    }
    entries.add(page);
    previous = page;
  }
  return entries;
}

/// A sort direction, as the `sortOrder` query value spells it.
enum SortOrder { asc, desc }

/// The one column a paginated route is sorted by (its `sortBy` value), and its direction.
class PageSort {
  const PageSort(this.by, this.order);

  final String by;
  final SortOrder order;

  @override
  bool operator ==(Object other) => other is PageSort && other.by == by && other.order == order;

  @override
  int get hashCode => Object.hash(by, order);
}

/// The sort after pressing [column]'s header under [current]: a column cycles
/// none, ascending, descending, none; another column's header starts ascending.
PageSort? nextSort(PageSort? current, String column) {
  if (current == null || current.by != column) {
    return PageSort(column, SortOrder.asc);
  }
  return current.order == SortOrder.asc ? PageSort(column, SortOrder.desc) : null;
}

/// The sort state of [column]'s header under [current]: `none`, `ascending` or `descending`.
String sortState(PageSort? current, String column) {
  if (current == null || current.by != column) {
    return 'none';
  }
  return current.order == SortOrder.asc ? 'ascending' : 'descending';
}

/// The declared page [sizes] a size selector offers: those the server accepts, at
/// most [maxLimit] (the envelope's; `0` before a page has loaded, so nothing yet).
List<int> offeredPageSizes(List<int> sizes, int maxLimit) => [
  for (final size in sizes)
    if (size <= maxLimit) size,
];

/// Everything one page request of a paginated route sends.
class PageQuery {
  const PageQuery(this.position, this.size, this.sort, this.filters);

  /// A row offset or a page index, as the backend counts positions.
  final int position;

  /// The rows per page the reader chose, or `null` for the server's own choice.
  final int? size;

  final PageSort? sort;

  /// The filters, as the filter bar's controls hold them, by filter name.
  final Map<String, String> filters;
}

class PagedBinding<T> extends SyncedBinding {
  /// [stopWhen] tests the rows shown, as [rows] reads them. [kept] is the
  /// binding's kept read: a page is kept by every argument its request sends.
  PagedBinding(Future<Page<T>> Function(PageQuery query) load, this._advance, {this._inputs, bool Function()? ready, Duration? poll, bool Function(List<T> rows)? stopWhen, int? maxPolls, bool Function()? session, this._accumulate = false, List<int> pageSizes = const [], this.firstLast = false, this.site, KeptPageCall<T>? kept}) : _declaredSizes = pageSizes {
    _page = Binding<Page<T>>(() => load(_query), inputs: () => [..._currentInputs(), _position, _size, _sort, _filters], ready: ready, session: session, poll: poll, stopWhen: stopWhen == null ? null : (_) => stopWhen(rows), maxPolls: maxPolls, kept: kept == null ? null : KeptCall<Page<T>>(kept.read, () => kept.args(_query)));
    _page.addListener(_pageChanged);
  }

  /// The page query the next request sends.
  PageQuery get _query => PageQuery(_position, _size, _sort, _filters);

  @override
  final ReadSite? site;

  final PositionAdvance _advance;
  final List<Object?> Function()? _inputs;
  final bool _accumulate;
  final List<int> _declaredSizes;
  late final Binding<Page<T>> _page;

  /// The position the next load sends: a row offset or a page index, per `_advance`.
  int _position = 0;

  /// The size, sort and filters every page request sends.
  int? _size;
  PageSort? _sort;
  Map<String, String> _filters = const {};

  /// The rows of the pages before this one, when accumulating.
  final List<T> _earlier = [];

  /// The size the first page loaded under; a later page cut under another size restarts.
  int? _limitSeen;
  List<Object?> _lastInputs = const [];
  bool _started = false;

  List<Object?> _currentInputs() => _inputs?.call() ?? const <Object?>[];

  Page<T>? get _current => _page.isLoaded ? _page.value : null;

  void _restart() {
    _position = 0;
    _earlier.clear();
    _limitSeen = null;
  }

  void _pageChanged() {
    final page = _current;
    if (_page.signedOut) {
      // The session ended: the pages passed under it are gone with it.
      _restart();
    } else if (page != null) {
      // A page that answers with a different size than the first page did was cut under a
      // size that has since changed (a redeploy moved the default): positions computed
      // under the old size are no longer page boundaries, so start over from the first page.
      if (_position == 0 || _limitSeen == null) {
        _limitSeen = page.limit;
      } else if (page.limit != _limitSeen) {
        _restart();
        _page.sync();
      }
    }
    notifyListeners();
  }

  /// The rows shown: this page's, or every page's so far when accumulating.
  List<T> get rows => _accumulate ? [..._earlier, ..._page.value.items] : _page.value.items;

  /// The data-binding contract's name for the rows shown; the same as `rows`.
  List<T> get value => rows;

  @override
  bool get isLoading => _page.isLoading;

  @override
  bool get isLoaded => _page.isLoaded;

  @override
  CruftFreeException? get error => _page.error;

  /// How many rows the whole chain selects.
  int get total => _current?.total ?? 0;

  /// The row the page shown starts at.
  int get offset => _current?.offset ?? 0;

  /// The rows per page the server applied.
  int get limit => _current?.limit ?? 0;

  /// The most rows per page the server accepts (`0` before a page has loaded).
  int get maxLimit => _current?.maxLimit ?? 0;

  /// The declared sizes the server accepts -- what the size selector offers.
  List<int> get pageSizes => offeredPageSizes(_declaredSizes, maxLimit);

  /// Whether the pager shows a first-page and a last-page control (`firstLastPager`).
  final bool firstLast;

  /// The size the selector shows chosen: the size requested, else the one applied.
  int get pageSize => _size ?? limit;

  /// The sort the rows are requested in.
  PageSort? get sort => _sort;

  /// How many pages exist (`0` when no row matches).
  int get pageCount => limit > 0 && total > 0 ? (total / limit).ceil() : 0;

  /// The page shown, zero-based.
  int get pageIndex => limit > 0 ? offset ~/ limit : 0;

  /// Whether rows exist past the page shown.
  bool get hasNext {
    final page = _current;
    return page != null && page.offset + page.items.length < page.total;
  }

  /// Whether a page before this one exists (never when accumulating).
  bool get hasPrevious => !_accumulate && offset > 0;

  /// The rows the page shown covers, or `null` until a page with rows has loaded.
  PageRange? get range {
    final page = _current;
    if (page == null || page.items.isEmpty) {
      return null;
    }
    return PageRange(page.offset + 1, page.offset + page.items.length, page.total);
  }

  /// The numbered pages the pager shows (`pageWindow`).
  List<int?> get window => pageWindow(pageCount, pageIndex);

  @override
  void sync() {
    // A change to what the call reads starts over from the first page.
    final inputs = _currentInputs();
    if (_started && !listEquals(inputs, _lastInputs)) {
      _restart();
    }
    _started = true;
    _lastInputs = inputs;
    _page.sync();
  }

  @override
  Future<void> refresh() => _page.refresh();

  @override
  bool get pollExhausted => _page.pollExhausted;

  @override
  bool get isPolling => _page.isPolling;

  @override
  int get pausedForMs => _page.pausedForMs;

  @override
  bool get isOffline => _page.isOffline;

  @override
  void resumePolling() => _page.resumePolling();

  /// Whether a rate-limited read paused the binding: it requests no other page,
  /// size, sort or filter then, like any changed input.
  bool get _paused => _page._paused;

  void next() {
    final page = _current;
    if (_paused || page == null || !hasNext) {
      return;
    }
    if (_accumulate) {
      _earlier.addAll(page.items);
    }
    goTo(pageIndex + 1);
  }

  void previous() {
    if (hasPrevious) {
      goTo(pageIndex - 1);
    }
  }

  /// Loads the first page; ignored while it is the one shown.
  void goToFirst() {
    if (hasPrevious) {
      goTo(0);
    }
  }

  /// Loads the last page; ignored while it is the one shown.
  void goToLast() {
    if (hasNext) {
      goTo(pageCount - 1);
    }
  }

  /// Loads the page at [index] (zero-based); an index outside the pages is ignored.
  void goTo(int index) {
    if (_paused || index < 0 || index >= pageCount) {
      return;
    }
    _position = _advance == PositionAdvance.rowOffset ? index * limit : index;
    _page.sync();
  }

  /// Requests pages of [size] rows, from the first page. The server bounds the size
  /// and refuses one outside its bounds; one that is not a positive number is refused here.
  void setPageSize(int size) {
    if (size < 1) {
      throw ArgumentError.value(size, 'size', 'A requested size is a positive whole number of rows');
    }
    if (_paused) {
      return;
    }
    _size = size;
    _restart();
    _page.sync();
  }

  /// Sorts by [sort] (or not at all), from the first page.
  void setSort(PageSort? sort) {
    if (_paused) {
      return;
    }
    _sort = sort;
    _restart();
    _page.sync();
  }

  /// Presses [column]'s header: none, ascending, descending, none -- from the first page.
  void toggleSort(String column) => setSort(nextSort(_sort, column));

  /// The sort state of [column]'s header.
  String sortStateOf(String column) => sortState(_sort, column);

  /// Filters by [filters] (the filter bar's control values, by filter name), from the first page.
  void setFilters(Map<String, String> filters) {
    if (_paused) {
      return;
    }
    _filters = Map.unmodifiable(filters);
    _restart();
    _page.sync();
  }

  @override
  void dispose() {
    _page.removeListener(_pageChanged);
    _page.dispose();
    super.dispose();
  }
}
